// CRT-Monitor: leichte Tonnen-Verzerrung, Scanlines, RGB-Maske, Vignette.
vec4 farbe(vec2 uv, vec4 src)
{
    vec2 d = uv - 0.5;
    vec2 kruemm = uv + d * dot(d, d) * 0.25;            // Tonnen-Verzerrung
    if (kruemm.x < 0.0 || kruemm.x > 1.0 || kruemm.y < 0.0 || kruemm.y > 1.0)
        return vec4(0.0, 0.0, 0.0, 1.0);
    vec3 farbe = texture(uTex, kruemm).rgb;
    float zeile = sin(kruemm.y * uResolution.y * 3.14159);
    farbe *= 0.82 + 0.18 * zeile * zeile;               // Scanlines
    float spalte = mod(floor(kruemm.x * uResolution.x), 3.0);
    vec3 maske = spalte < 1.0 ? vec3(1.0, 0.72, 0.72)
               : spalte < 2.0 ? vec3(0.72, 1.0, 0.72) : vec3(0.72, 0.72, 1.0);
    farbe *= maske * 1.12;                              // Lochmaske
    farbe *= 1.0 - 0.55 * dot(d, d) * 2.0;             // Vignette
    return vec4(farbe, 1.0);
}
